import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Влияние гильдий","description":"","frontmatter":{"pageId":"players/guild-influence","contentRevision":1},"headers":[],"relativePath":"ru/players/guild-influence.md","filePath":"ru/players/guild-influence.md"}'),t={name:"ru/players/guild-influence.md"};function n(o,e,s,d,u,c){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="влияние-гильдии" tabindex="-1">Влияние гильдий <a class="header-anchor" href="#влияние-гильдии" aria-label="Permalink to &quot;Влияние гильдий&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Открой <strong>Зоны влияния гильдий → Настройки</strong> на мировой карте или настройки влияния в союзе. Выбери домашнюю поверхностную колонию и явно опубликуй влияние. Это раскрывает название союза и цвет, но не казну, состав и чат. По умолчанию публикации нет.</p><p>Радиус — 3 соседних шага по суше, сила 4 − расстояние. Вода останавливает распространение. У одного союза берётся максимум, не сумма; равная сила разных союзов даёт нейтральную штриховку. Владелец союза выбирает один из 16 цветов. Офлайн-источники учитываются.</p><p>Локальный переключатель слоя не отзывает согласие. Для отзыва используй отдельную кнопку: версия согласия меняется даже при уже выключенной публикации, блокируя запоздавший запрос включения.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Это не владение, войны, аванпосты или право доступа. Максимум 128 активных источников на весь сервер. При превышении импортированной БД слой целиком недоступен. Reset/выход/роспуск отзывают согласие; восстановление архива перепроверяет контекст и вместимость. Администратор может выключить, но не включить за игрока.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./community">Профили, друзья и союзы</a></li><li><a href="./world">Общая планета и поселения</a></li><li><a href="./../admins/api">Справочник REST API</a></li></ul>',10)])])}const m=a(t,[["render",n]]);export{h as __pageData,m as default};
